# Extract full review texts for classification
full_reviews = []
for i, (date, user, text) in enumerate(matches, 1):
    text = text.strip()
    if "Recall: the preceding lines contain" in text:
        text = text.split("Recall: the preceding lines contain")[0].strip()
    full_reviews.append({
        'num': i,
        'text': text
    })

# Create classification prompts
prompts = []
for r in full_reviews:
    prompt = f"""Review: {r['text']}

Classify this movie review as either 'positive' or 'negative'. Respond with only one word: positive or negative."""
    prompts.append(prompt)

# Batch classify all 9 reviews
classifications = llm_query_batched(prompts)
print("Classifications:")
for i, (r, cls) in enumerate(zip(full_reviews, classifications), 1):
    print(f"{i}. {cls.strip()}")
